#include "code_scan.h"
#include "checks_quality.h"
int check_magic_number(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_NUMBER){long long v=f->tokens[i].val;if(v!=0&&v!=1&&v!=-1&&(v<(-100)||v>100)&&v!=32&&v!=10&&v!=100&&v!=1000){int is_define=0;for(int j=i-1;j>=0&&j>i-3;j--){if(f->tokens[j].type==TK_EQ||f->tokens[j].type==TK_LT||f->tokens[j].type==TK_GT||f->tokens[j].type==TK_LPAREN||f->tokens[j].type==TK_RETURN||f->tokens[j].type==TK_COMMA)continue;if(f->tokens[j].type==TK_ID){is_define=1;break;}break;}if(!is_define){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7001;snprintf(out->msg,sizeof(out->msg),"Magic number %lld - consider using a named constant",v);snprintf(out->suggestion,sizeof(out->suggestion),"Replace with #define or const variable");}}}}}return cnt;}
int check_deep_nesting(SourceFile*f,Project*p,Issue*out){int cnt=0;int depth=0;int max_depth=0;int max_line=0;int i; for(i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_FOR||f->tokens[i].type==TK_WHILE||f->tokens[i].type==TK_DO||f->tokens[i].type==TK_IF||f->tokens[i].type==TK_SWITCH||f->tokens[i].type==TK_CASE){depth++;if(depth>max_depth){max_depth=depth;max_line=f->tokens[i].line;}}if(f->tokens[i].type==TK_RBRACE||f->tokens[i].type==TK_BLOCK_CLOSE){depth--;if(depth<0)depth=0;}}if(max_depth>5){cnt++;if(cnt==1&&out){out->loc.line=max_line;out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7002;snprintf(out->msg,sizeof(out->msg),"Deep nesting detected (depth %d)",max_depth);snprintf(out->suggestion,sizeof(out->suggestion),"Refactor into smaller functions to reduce nesting");}}return cnt;}
int check_long_function(SourceFile*f,Project*p,Issue*out){int cnt=0;int func_start=-1;char func_name[256]="";int func_lines=0;int start_line=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){snprintf(func_name,sizeof(func_name),"%s",f->tokens[i].text);func_start=j;start_line=f->tokens[i].line;int body_depth=1;int k=j+1;int last_line=start_line;while(k<f->ntokens&&body_depth>0){if(f->tokens[k].type==TK_BLOCK_OPEN||f->tokens[k].type==TK_LBRACE)body_depth++;if(f->tokens[k].type==TK_BLOCK_CLOSE||f->tokens[k].type==TK_RBRACE)body_depth--;last_line=f->tokens[k].line;k++;}func_lines=last_line-start_line;if(func_lines>200){cnt++;if(cnt==1&&out){LOC_TOK(out,f,func_start);out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7003;snprintf(out->msg,sizeof(out->msg),"Function '%s' is %d lines long - consider refactoring",func_name,func_lines);snprintf(out->suggestion,sizeof(out->suggestion),"Split into smaller functions of <50 lines each");}}}}}return cnt;}
int check_many_params(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){int params=0;int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN){depth--;if(depth==0)break;}if(depth==1&&f->tokens[j].type==TK_COMMA)params++;j++;}if(params>6){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7004;snprintf(out->msg,sizeof(out->msg),"Function '%s' has %d parameters",f->tokens[i].text,params+1);snprintf(out->suggestion,sizeof(out->suggestion),"Consider passing a struct or reducing parameters");}}}}return cnt;}
int check_global_var(SourceFile*f,Project*p,Issue*out){int cnt=0;int global_count=0;char last_type[256]="";for(int i=0;i<f->ntokens-2;i++){TokenType t=f->tokens[i].type;if(t==TK_INT||t==TK_CHAR||t==TK_FLOAT||t==TK_DOUBLE||t==TK_LONG||t==TK_SHORT||t==TK_VOID||t==TK_STRUCT||t==TK_UNION){if(i+1<f->ntokens&&f->tokens[i+1].type==TK_ID&&!lexer_is_keyword(f->tokens[i+1].text)){int j=i+2;int is_func=0;while(j<f->ntokens&&f->tokens[j].type!=TK_SEMI&&f->tokens[j].type!=TK_EOF){if(f->tokens[j].type==TK_LPAREN){is_func=1;break;}j++;}if(!is_func){global_count++;}}}}if(global_count>10){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7005;snprintf(out->msg,sizeof(out->msg),"File has %d global variables - consider encapsulation",global_count);snprintf(out->suggestion,sizeof(out->suggestion),"Move globals into structs or use static scope");}}return cnt>0?1:cnt;}
int check_missing_const(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_STAR&&f->tokens[i+2].type==TK_ID){int has_const=0;for(int j=i-1;j>=0&&j>i-5;j--){if(f->tokens[j].type==TK_CONST){has_const=1;break;}}if(!has_const){int is_param=0;for(int j=i+3;j<f->ntokens&&j<i+10;j++){if(f->tokens[j].type==TK_RPAREN){is_param=1;break;}if(f->tokens[j].type==TK_SEMI)break;}if(is_param){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7006;snprintf(out->msg,sizeof(out->msg),"Pointer parameter '%s' could be const",f->tokens[i+2].text);snprintf(out->suggestion,sizeof(out->suggestion),"Add const to pointer parameter if not modified");}}}}}return cnt;}
int check_shadowed_var(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_INT||f->tokens[i].type==TK_CHAR||f->tokens[i].type==TK_FLOAT||f->tokens[i].type==TK_DOUBLE){if(i+1<f->ntokens&&f->tokens[i+1].type==TK_ID){char*name=f->tokens[i+1].text;for(int j=i-1;j>=0&&j>i-100;j--){if(f->tokens[j].type==TK_ID&&strcmp(f->tokens[j].text,name)==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i+1);out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7007;snprintf(out->msg,sizeof(out->msg),"Variable '%s' shadows outer declaration",name);}break;}}}}}return cnt;}
int check_unused_var(SourceFile*f,Project*p,Issue*out){int cnt=0;typedef struct{char name[256];int line;int used;int is_param;}Var;Var*vars=NULL;int nvars=0;int cap=0;for(int i=0;i<f->ntokens-2;i++){TokenType t=f->tokens[i].type;if(t==TK_INT||t==TK_CHAR||t==TK_FLOAT||t==TK_DOUBLE||t==TK_LONG||t==TK_SHORT){if(i+1<f->ntokens&&f->tokens[i+1].type==TK_ID){int is_param=0;for(int j=i+2;j<f->ntokens&&j<i+10;j++){if(f->tokens[j].type==TK_LPAREN){is_param=1;break;}if(f->tokens[j].type==TK_SEMI)break;}if(!is_param&&nvars<100){if(nvars>=cap){cap=cap?cap*2:64;vars=realloc(vars,cap*sizeof(Var));}snprintf(vars[nvars].name,sizeof(vars[nvars].name),"%s",f->tokens[i+1].text);vars[nvars].line=f->tokens[i+1].line;vars[nvars].used=0;vars[nvars].is_param=0;nvars++;}}}}for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){for(int j=0;j<nvars;j++){if(strcmp(f->tokens[j].text,f->tokens[i].text)==0){vars[j].used=1;}}}}for(int i=0;i<nvars;i++){if(!vars[i].used){cnt++;if(cnt==1&&out){out->loc.line=vars[i].line;out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7008;snprintf(out->msg,sizeof(out->msg),"Unused variable '%s'",vars[i].name);snprintf(out->suggestion,sizeof(out->suggestion),"Remove unused variable or add (void) cast");}}}free(vars);return cnt;}
int check_unused_func(SourceFile*f,Project*p,Issue*out){int cnt=0;typedef struct{char name[256];int defined;int called;}Func;Func*funcs=NULL;int nf=0;int cf=0;for(int i=0;i<f->ntokens-1;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){char*fname=f->tokens[i].text;int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}int is_def=(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE));int found=0;for(int k=0;k<nf;k++){if(strcmp(funcs[k].name,fname)==0){funcs[k].called=1;found=1;break;}}if(!found){if(nf>=cf){cf=cf?cf*2:64;funcs=realloc(funcs,cf*sizeof(Func));}snprintf(funcs[nf].name,sizeof(funcs[nf].name),"%s",fname);funcs[nf].defined=is_def;funcs[nf].called=0;nf++;}}}for(int i=0;i<nf;i++){if(funcs[i].defined&&!funcs[i].called){cnt++;if(cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7009;snprintf(out->msg,sizeof(out->msg),"Function '%s' is defined but never called",funcs[i].name);}}}free(funcs);return cnt;}
int check_assignment_in_cond(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if((f->tokens[i].type==TK_IF||f->tokens[i].type==TK_WHILE)&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;if(depth==1&&f->tokens[j].type==TK_EQ&&f->tokens[j-1].type!=TK_EQ&&f->tokens[j+1].type!=TK_EQ){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7010;snprintf(out->msg,sizeof(out->msg),"Assignment in conditional - possible typo for ==");snprintf(out->suggestion,sizeof(out->suggestion),"Use == for comparison, or add extra parentheses if intentional");}}j++;}}}return cnt;}
int check_comma_operator(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_RPAREN&&f->tokens[i+1].type==TK_COMMA&&f->tokens[i+2].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7011;snprintf(out->msg,sizeof(out->msg),"Comma operator used in function arguments - may be confusing");}}}return cnt;}
int check_goto_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_GOTO){cnt++;}}if(cnt>0&&out){out->loc.line=0;out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7012;snprintf(out->msg,sizeof(out->msg),"File uses goto (%d times) - consider structured programming",cnt);snprintf(out->suggestion,sizeof(out->suggestion),"Use break/continue/return or structured error handling");return cnt;}return cnt>0?1:0;}
int check_switch_without_default(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_SWITCH){int has_default=0;int j=i+1;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)depth++;if(f->tokens[j].type==TK_BLOCK_CLOSE||f->tokens[j].type==TK_RBRACE)depth--;if(f->tokens[j].type==TK_DEFAULT)has_default=1;j++;}if(!has_default){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7013;snprintf(out->msg,sizeof(out->msg),"Switch statement without default case");snprintf(out->suggestion,sizeof(out->suggestion),"Add a default case to handle unexpected values");}}}}return cnt;}
int check_missing_break(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_CASE){int has_break=0;int j=i+1;while(j<f->ntokens){if(f->tokens[j].type==TK_BREAK||f->tokens[j].type==TK_RETURN){has_break=1;break;}if(f->tokens[j].type==TK_CASE||f->tokens[j].type==TK_DEFAULT||f->tokens[j].type==TK_RBRACE||f->tokens[j].type==TK_BLOCK_CLOSE)break;j++;}if(!has_break){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_QUALITY;out->code=7014;snprintf(out->msg,sizeof(out->msg),"Case without break - fallthrough");}}}}return cnt;}
int check_function_complexity(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){char*fname=f->tokens[i].text;int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){int decisions=0;int body_depth=1;int k=j+1;while(k<f->ntokens&&body_depth>0){if(f->tokens[k].type==TK_BLOCK_OPEN||f->tokens[k].type==TK_LBRACE)body_depth++;if(f->tokens[k].type==TK_BLOCK_CLOSE||f->tokens[k].type==TK_RBRACE)body_depth--;if(body_depth==0)break;if(f->tokens[k].type==TK_IF||f->tokens[k].type==TK_WHILE||f->tokens[k].type==TK_FOR||f->tokens[k].type==TK_CASE)decisions++;k++;}if(decisions>10){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7015;snprintf(out->msg,sizeof(out->msg),"Function '%s' has high cyclomatic complexity (%d decisions)",fname,decisions);snprintf(out->suggestion,sizeof(out->suggestion),"Refactor into smaller functions to reduce complexity");}}}}}return cnt;}
int check_too_many_locals(SourceFile*f,Project*p,Issue*out){int cnt=0;int func_start=-1;char func_name[256]="";int locals=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){snprintf(func_name,sizeof(func_name),"%s",f->tokens[i].text);func_start=j;locals=0;int body_depth=1;int k=j+1;while(k<f->ntokens&&body_depth>0){if(f->tokens[k].type==TK_BLOCK_OPEN||f->tokens[k].type==TK_LBRACE)body_depth++;if(f->tokens[k].type==TK_BLOCK_CLOSE||f->tokens[k].type==TK_RBRACE)body_depth--;if(body_depth==0)break;if((f->tokens[k].type==TK_INT||f->tokens[k].type==TK_CHAR||f->tokens[k].type==TK_FLOAT||f->tokens[k].type==TK_DOUBLE)&&k+1<f->ntokens&&f->tokens[k+1].type==TK_ID)locals++;k++;}if(locals>15){cnt++;if(cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7016;snprintf(out->msg,sizeof(out->msg),"Function '%s' has %d local variables",func_name,locals);}}}}}return cnt;}
int check_mixed_declarations(SourceFile*f,Project*p,Issue*out){int cnt=0;int i;int in_func=0;int first_decl_line=0;for(i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LPAREN){int j=i+2;int depth=1;while(j<f->ntokens&&depth>0){if(f->tokens[j].type==TK_LPAREN)depth++;if(f->tokens[j].type==TK_RPAREN)depth--;j++;}if(j<f->ntokens&&(f->tokens[j].type==TK_BLOCK_OPEN||f->tokens[j].type==TK_LBRACE)){in_func=1;first_decl_line=0;}}}if(in_func&&i>0&&i<f->ntokens&&(f->tokens[i].type==TK_INT||f->tokens[i].type==TK_CHAR||f->tokens[i].type==TK_FLOAT||f->tokens[i].type==TK_DOUBLE)&&i+1<f->ntokens&&f->tokens[i+1].type==TK_ID){if(first_decl_line==0)first_decl_line=f->tokens[i].line;else if(f->tokens[i].line>first_decl_line+2){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7017;snprintf(out->msg,sizeof(out->msg),"Mixed declarations and code (C99 style)");snprintf(out->suggestion,sizeof(out->suggestion),"Declare all variables at the beginning of the block");}}}if(i>0&&i<f->ntokens&&(f->tokens[i].type==TK_RBRACE||f->tokens[i].type==TK_BLOCK_CLOSE))in_func=0;return cnt;}
int check_trailing_whitespace(SourceFile*f,Project*p,Issue*out){int cnt=0;char*content=f->content;if(!content)return 0;long long len=(long long)strlen(content);for(long long i=0;i<len;i++){if(content[i]==' '||content[i]=='\t'){if(i+1==len||content[i+1]=='\n'||content[i+1]=='\r'){cnt++;}}}if(cnt>10&&cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7018;snprintf(out->msg,sizeof(out->msg),"Trailing whitespace detected (%d instances)",cnt);}return cnt>10?1:0;}
int check_tab_vs_spaces(SourceFile*f,Project*p,Issue*out){int cnt=0;char*content=f->content;if(!content)return 0;int has_tabs=0;int has_spaces=0;for(long long i=0;content[i];i++){if(content[i]=='\t')has_tabs=1;if(content[i]==' '&&content[i+1]==' '&&content[i+2]==' ')has_spaces=1;}if(has_tabs&&has_spaces){cnt++;if(cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7019;snprintf(out->msg,sizeof(out->msg),"Mixed tab and space indentation");}}return cnt;}
int check_long_line(SourceFile*f,Project*p,Issue*out){int cnt=0;char*content=f->content;if(!content)return 0;int line=1;int col=1;for(long long i=0;content[i];i++){if(content[i]=='\n'){line++;col=1;}else{col++;if(col>120){cnt++;col=0;while(content[i]&&content[i]!='\n')i++;line++;}}}if(cnt>5&&cnt==1&&out){out->sev=SEV_INFO;out->cat=CAT_QUALITY;out->code=7020;snprintf(out->msg,sizeof(out->msg),"Lines exceeding 120 characters (%d occurrences)",cnt);}return cnt>5?1:cnt;}
